const mongoose = require("mongoose");

const catalogueSyncEventSchema = new mongoose.Schema(
  {
    businessId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "Business",
      required: true,
    },

    // Unique ID generated by the device and reused on retries.
    operationId: {
      type: String,
      required: true,
    },

    deviceId: {
      type: String,
      required: true,
    },

    performedBy: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "User",
      required: true,
    },

    entityType: {
      type: String,
      enum: ["product", "category"],
      required: true,
    },

    entityId: {
      type: mongoose.Schema.Types.ObjectId,
      required: true,
    },

    action: {
      type: String,
      enum: ["create", "update", "deactivate"],
      required: true,
    },

    entityVersion: {
      type: Number,
      required: true,
    },

    // Ordered, business-specific download cursor.
    sequence: {
      type: Number,
      required: true,
    },

    // Snapshot after the successful operation.
    snapshot: {
      type: mongoose.Schema.Types.Mixed,
      required: true,
    },
  },
  { timestamps: true },
);

catalogueSyncEventSchema.index(
  { businessId: 1, operationId: 1 },
  { unique: true },
);

catalogueSyncEventSchema.index(
  { businessId: 1, sequence: 1 },
  { unique: true },
);

const CatalogueSyncEvent = mongoose.model(
  "CatalogueSyncEvent",
  catalogueSyncEventSchema,
);

module.exports = CatalogueSyncEvent;
